using System;
using System.Diagnostics;
using System.IO;
using System.Net.Http;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Debug = UnityEngine.Debug;

namespace SousTension.Spikes.MovingFrame.EditorTools
{
    /// <summary>
    /// Playable setup of the spike (E1-11): the scene, the local Nakama server and the development build used as the second client.
    /// Menu SousTension > Spike. The scene is generated by code (no hand-written YAML) and can be regenerated headlessly:
    ///   Unity -batchmode -projectPath . -executeMethod SousTension.Spikes.MovingFrame.EditorTools.PlayLocal.CreateSceneBatch -quit
    /// The server (server/docker-compose.yml) runs in DEBUG mode (SOUSTENSION_DEBUG=1): the developer console (key left of 1) works there.
    /// </summary>
    public static class PlayLocal
    {
        public const string ScenePath = "Assets/_Spikes/MovingFrame/Scenes/MovingFrame.unity";
        public const string BuildPath = "Builds/Dev/SousTension.exe";
        public const string HealthUrl = "http://127.0.0.1:7350/healthcheck";

        private static string ProjectRoot => Directory.GetParent(Application.dataPath).FullName;

        // ---- the scene -------------------------------------------------------------------------------------------------------------

        [MenuItem("SousTension/Spike/1. Create the MovingFrame scene")]
        public static void CreateScene()
        {
            if (EditorApplication.isPlaying) { Debug.LogWarning("[PlayLocal] stop Play mode first"); return; }
            Directory.CreateDirectory(Path.Combine(ProjectRoot, Path.GetDirectoryName(ScenePath)));
            var scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);
            var root = new GameObject("MovingFrameBootstrap");
            root.AddComponent<MovingFrameBootstrap>();                         // builds the boat, services, model, controller and views at Play
            EditorSceneManager.SaveScene(scene, ScenePath);
            AssetDatabase.Refresh();
            Debug.Log("[PlayLocal] scene saved: " + ScenePath);
        }

        /// <summary>Entry point for -executeMethod (batch mode).</summary>
        public static void CreateSceneBatch() => CreateScene();

        // ---- the server ------------------------------------------------------------------------------------------------------------

        [MenuItem("SousTension/Spike/2. Start the local server (Docker)")]
        public static bool StartServer()
        {
            if (IsServerUp()) { Debug.Log("[PlayLocal] the server already answers on " + HealthUrl); return true; }
            var info = new ProcessStartInfo("docker", "compose -f server/docker-compose.yml up -d")
            {
                WorkingDirectory = ProjectRoot, UseShellExecute = false, CreateNoWindow = true,
                RedirectStandardOutput = true, RedirectStandardError = true
            };
            try
            {
                using (var p = Process.Start(info))
                {
                    p.WaitForExit(180000);
                    string output = p.StandardOutput.ReadToEnd() + p.StandardError.ReadToEnd();
                    if (p.ExitCode != 0) { Debug.LogError("[PlayLocal] docker compose failed (is Docker started?)\n" + output); return false; }
                }
            }
            catch (Exception e) { Debug.LogError("[PlayLocal] cannot run docker: " + e.Message); return false; }
            var deadline = DateTime.UtcNow.AddSeconds(90);
            while (DateTime.UtcNow < deadline)
            {
                if (IsServerUp()) { Debug.Log("[PlayLocal] the server is up (debug mode)."); return true; }
                System.Threading.Thread.Sleep(1000);
            }
            Debug.LogError("[PlayLocal] the server did not answer within 90 s: " + HealthUrl);
            return false;
        }

        public static bool IsServerUp()
        {
            try
            {
                using (var http = new HttpClient { Timeout = TimeSpan.FromSeconds(2) })
                    return http.GetAsync(HealthUrl).Result.IsSuccessStatusCode;
            }
            catch { return false; }
        }

        // ---- play ------------------------------------------------------------------------------------------------------------------

        [MenuItem("SousTension/Spike/3. Play locally (server + scene)")]
        public static void Play()
        {
            if (!StartServer()) return;
            if (!File.Exists(Path.Combine(ProjectRoot, ScenePath))) CreateScene();
            EditorSceneManager.OpenScene(ScenePath);
            EditorApplication.isPlaying = true;
        }

        // ---- the second client ------------------------------------------------------------------------------------------------------

        [MenuItem("SousTension/Spike/4. Build the Windows development client (player 2)")]
        public static void BuildDevClient()
        {
            if (!File.Exists(Path.Combine(ProjectRoot, ScenePath))) CreateScene();
            string output = Path.Combine(ProjectRoot, BuildPath);
            Directory.CreateDirectory(Path.GetDirectoryName(output));
            var report = BuildPipeline.BuildPlayer(new BuildPlayerOptions
            {
                scenes = new[] { ScenePath },
                locationPathName = output,
                target = BuildTarget.StandaloneWindows64,
                options = BuildOptions.Development
            });
            Debug.Log("[PlayLocal] build " + report.summary.result + " -> " + output + " (" + (long)report.summary.totalSize / (1024 * 1024) + " MB, "
                      + report.summary.totalErrors + " errors). Launch clients with tools/play-local.ps1");
        }

        /// <summary>Entry point for -executeMethod (batch mode).</summary>
        public static void BuildDevClientBatch() => BuildDevClient();
    }
}
